// Gmail HTML & Content Normalizer
const item = $input.first().json;

const externalId = item.id || item.messageId || `gmail_${Date.now()}`;
const sender = item.from?.value?.[0]?.address || item.from || 'unknown@gmail.com';
const subject = item.subject || 'No Subject';
const rawBody = item.text || item.snippet || item.html || '';

// Strip HTML tags, tracking pixels, and excessive whitespace
let cleanContent = rawBody
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();

if (subject && subject !== 'No Subject' && !cleanContent.toLowerCase().includes(subject.toLowerCase())) {
  cleanContent = `Subject: ${subject}\n${cleanContent}`;
}

const timestamp = item.date ? new Date(item.date).toISOString() : new Date().toISOString();
const threadId = item.threadId || null;
const labels = item.labelIds || [];

return [{
  json: {
    source: 'GMAIL',
    externalId,
    sender,
    subject,
    content: cleanContent,
    timestamp,
    metadata: {
      threadId,
      labels
    }
  }
}];
